/**
 * Test utilities
 * */
std::pair<bool, std::string> read_file(const std::string& pathname) {
  std::ifstream file(pathname, std::ios::in);
  if (file) {
    std::string buffer;
    file.seekg(0, std::ios::end);
    buffer.reserve((std::string::size_type)file.tellg());
    file.seekg(0, std::ios::beg);
    buffer.assign((std::istreambuf_iterator<char>(file)),
                  std::istreambuf_iterator<char>());

    return {true, buffer};
  }
  return {false, ""};
}

void write_to_file(const std::string& filename,
                   bool is_binary,
                   std::function<void(std::ostream&)> write) {
  std::ios_base::openmode mode =
      std::ios::out |
      (is_binary ? std::ios::binary : static_cast<std::ios_base::openmode>(0));
  std::fstream file(filename, mode);
  if (file) {
    write(file);
  } else {
    LOG(WARNING) << "Failed to write file \'" + filename + "\'";
  }
}

// Derive the validator target from the blob's own declared SPIR-V version, so
// this keeps working when the compiler's target version moves instead of having
// to be edited in lockstep with it.
spv_target_env spirv_target_env_for(const spirv_t& spirv) {
  // Word 1 of the SPIR-V header holds the version as 0x00MMmm00
  constexpr size_t kVersionWord = 1;
  CHECK_GT(spirv.size(), kVersionWord);
  auto const major = (spirv[kVersionWord] >> 16) & 0xFF;
  auto const minor = (spirv[kVersionWord] >> 8) & 0xFF;

  switch ((major << 8) | minor) {
    case 0x0106:
      return SPV_ENV_VULKAN_1_3;
    case 0x0105:
      return SPV_ENV_VULKAN_1_2;
    case 0x0104:
      return SPV_ENV_VULKAN_1_1_SPIRV_1_4;
    default:
      return SPV_ENV_VULKAN_1_1;
  }
}

std::pair<bool, std::string> validate_spirv(const spirv_t& spirv) {
  std::string messages;
  spvtools::SpirvTools tools(spirv_target_env_for(spirv));
  tools.SetMessageConsumer([&messages](spv_message_level_t,
                                       const char*,
                                       const spv_position_t& position,
                                       const char* message) {
    messages += "  word " + std::to_string(position.index) + ": " + message + '\n';
  });

  // Validate under the same layout rules the renderer actually runs with. The
  // shader library declares its uniform blocks `layout(std430)`, which the
  // default "extended" UBO rules reject, so without these the validator is
  // stricter than any device we will ever run on and reports false failures.
  //
  // Both features are hard requirements, not opportunistic: isDeviceSuitable in
  // VulkanPlatform.cpp rejects a device that lacks either, and
  // createDeviceContext enables both unconditionally. If that ever stops being
  // true, this needs to change with it.
  spvtools::ValidatorOptions options;
  options.SetUniformBufferStandardLayout(true);
  options.SetScalarBlockLayout(true);

  return {tools.Validate(spirv.data(), spirv.size(), options), messages};
}

std::string reflection_to_string(const ShaderReflection& reflection) {
  std::ostringstream stream;
  reflection.serialize(stream);
  return stream.str();
}

// gtest's diff of two multi-line strings is near-unreadable, and the whole point
// of a text golden is that a human can see which binding moved, so report the
// first differing line instead of dumping both documents.
void expect_reflection_eq(const std::string& expected,
                          const std::string& actual,
                          const std::string& pathname) {
  std::istringstream expected_stream(expected);
  std::istringstream actual_stream(actual);
  std::string expected_line, actual_line;

  for (int line_number = 1;; line_number++) {
    bool const got_expected =
        static_cast<bool>(std::getline(expected_stream, expected_line));
    bool const got_actual = static_cast<bool>(std::getline(actual_stream, actual_line));

    if (!got_expected && !got_actual) {
      return;
    }

    if (got_expected != got_actual || expected_line != actual_line) {
      ADD_FAILURE() << "Reflection differs from " << pathname << " at line "
                    << line_number << "\n  expected: "
                    << (got_expected ? expected_line : "<end of file>")
                    << "\n  actual:   " << (got_actual ? actual_line : "<end of file>")
                    << "\nIf this change is intended, re-run with --regenerate-reflect "
                       "and review the diff.";
      return;
    }
  }
}

// ItemInfo has no operator<<, so a direct EXPECT_EQ on it reports a hex blob.
// Compare field by field instead, naming the field that differs.
void expect_item_info_eq(const ShaderReflection::ItemInfo& actual,
                         const ShaderReflection::ItemInfo& expected,
                         std::string_view description) {
  EXPECT_EQ(actual.set, expected.set) << description << " set";
  EXPECT_EQ(actual.binding_or_location, expected.binding_or_location)
      << description << " binding/location";
  EXPECT_EQ(actual.offset, expected.offset) << description << " offset";
  EXPECT_EQ(actual.block_or_array_size, expected.block_or_array_size)
      << description << " block/array size";
}

ShaderManager::BuilderUqPtr deserialize_builder(const std::string& filename,
                                                ShaderManager& shaderMgr) {
  auto read_result = read_file(filename);
  if (read_result.first) {
    return shaderMgr.deserializeBuilder(read_result.second);
  } else {
    return nullptr;
  }
}

/**
 * Fixture that initializes and destroys the Library and ShaderMgr for each
 * test. This stress tests startup and shutdown and tests that any shader
 * works as the first shader compiled.
 * */
template <typename GTEST_BASE>
class ShaderCompilerTest : public GTEST_BASE {
 public:
  // Since this fixture is a semi-stress test for init/shutdown, use SetUp()
  // instead of ctor for test environment to allow ASSERT* macros
  void SetUp() override {
    // create shader library
    auto library = std::make_unique<Library>();
    ASSERT_NE(nullptr, library) << "Failed to create Library";

    // add all the core shaders
    QueryRendererShaders::ShaderLibraryAutoGenerated::add_all_to_library(
        [&](auto const& item) {
          ASSERT_NO_THROW(library->add(
              item.internal_name, item.class_name, item.language, item.source))
              << "Library::add() threw an exception";
        });

    // add the RenderTests shaders
    library->addFromManifestFile("ShaderManifest.json", g_shaders_path);

    // create shader manager
    shaderMgr = std::make_unique<ShaderManager>(std::move(library));
    ASSERT_NE(nullptr, shaderMgr) << "Failed to create ShaderMgr";
  }

  void TearDown() override {
    ASSERT_NO_THROW(shaderMgr = nullptr) << "ShaderManager destructor threw an exception";
  }

  /**
   * Test functions
   * */
  // Compiles one builder file and checks the result two ways: the SPIR-V must
  // pass spirv-val, and the reflection must match a checked-in golden.
  //
  // Deliberately not a byte comparison against a .spv golden. That form could
  // only ever answer "did the bytes change", never "did the meaning change", so
  // every toolchain bump forced a blind regeneration of the goldens and the
  // test went quiet exactly when it was most needed.
  void loadBuilderFileCompileAndCheck(const std::string& testDirInputs,
                                      const std::string& testDirResults,
                                      const std::string& testName) {
    std::string builder_pathname = testDirInputs + testName + ".builder";
    std::string results_pathname = testDirResults + testName + ".reflect";

    auto builder = deserialize_builder(builder_pathname, *shaderMgr);
    ASSERT_NE(builder, nullptr)
        << "Failed to deserialize builder file: " << builder_pathname;

    // createCacheVector, not createCache: only the vector form passes a
    // redecorator to buildSpirv, and without one the cache's reflection is
    // left empty, which would make the assertions below vacuous
    ShaderManager::BuilderUqPtrVector builders;
    builders.push_back(std::move(builder));
    ShaderCacheShPtrVector caches;
    ASSERT_NO_THROW(caches = shaderMgr->createCacheVector(std::move(builders)));
    ASSERT_EQ(caches.size(), size_t(1));

    auto const& spirv_gen = caches[0]->getSpirv();
    ASSERT_FALSE(spirv_gen.empty()) << "No SPIR-V generated for " << testName;

    auto const [spirv_valid, validation_messages] = validate_spirv(spirv_gen);
    EXPECT_TRUE(spirv_valid) << "spirv-val rejected " << testName << ":\n"
                             << validation_messages;

    auto const reflection_string = reflection_to_string(caches[0]->getReflection());

    if (g_regenerate_reflect) {
      LOG(WARNING) << "Regenerating " << results_pathname;
      write_to_file(
          results_pathname, false, [&](auto& file) { file << reflection_string; });
    }

    auto const [read_ok, expected_reflection] = read_file(results_pathname);
    ASSERT_TRUE(read_ok) << "Failed to read reflection file: " << results_pathname
                         << "\nRun with --regenerate-reflect to create it.";

    expect_reflection_eq(expected_reflection, reflection_string, results_pathname);
  }

 protected:
  ShaderManagerUqPtr shaderMgr;
};

