//
using GeneralShaderCompilerTest = ShaderCompilerTest<::testing::Test>;
TEST_F(GeneralShaderCompilerTest, SerializationTest) {
  auto default_resource_limits_string =
      GetTBuiltInResourceString(DefaultTBuiltInResource);
  TBuiltInResource resource_limits{};
  DecodeResourceLimits(&resource_limits,
                       const_cast<char*>(default_resource_limits_string.c_str()));
  EXPECT_EQ(
      std::memcmp(&resource_limits, &DefaultTBuiltInResource, sizeof(TBuiltInResource)),
      0);
}

